class Person:
    def __init__(self, name="John", status=0):
        self.name = name
        self.status = status

# Simulate memory allocation by creating a new Person instance
def allocate_memory(size):
    # In Python, we don't manually manage memory like in C/C++
    # But for the sake of this example, we simulate allocation
    if size < 0:
        raise ValueError("Size must be non-negative")
    return Person()

# Allocate memory for a person
person_ptr = allocate_memory(100)

# Print the name and status of the person
print(f"Name: {person_ptr.name}")
print(f"Status: {person_ptr.status}")

