class MemoryBlock:
    def __init__(self, size):
        self.size = size
        self.data = [0] * size
        self.pointer = 0

    def get_pointer(self):
        return self.pointer

    def set_value(self, index, value):
        if 0 <= index < self.size:
            self.data[index] = value

    def get_value(self, index):
        if 0 <= index < self.size:
            return self.data[index]
        return None

    def free(self):
        self.data = None

def allocate_memory(size):
    return MemoryBlock(size)

def main():
    # Alokasi memori dengan ukuran 10
    memory_block = allocate_memory(10)

    # Membuat orang baru dan menetapkan status menjadi 0 dan nama menjadi "John"
    person = {"status": 0, "name": "John"}

